// ── CLEAN OUTPUT (buang semua tag) ──
let cleanOutput = aiOutput
  .replace(/\[\s*SEND_MEDIA\s*(?::[^\]]*)?\]/gi, '')
  .replace(/\[\s*SCHEDULE_SURVEY\b[^\]]*\]/gi, '')
  .replace(/\[REQUEST_CALL\]/gi, '')
  .replace(/\[TALK_TO_ADMIN\]/gi, '')
  .replace(/\[UNKNOWN\]/gi, '')
  .replace(/\[\s*FACTS\b[^\]]*\]/gi, '');

const preInternalStrip = cleanOutput;
const internalKeywords = ['berdasarkan faq','berdasarkan data','menurut data','dari faq','dari sheet','data terverifikasi','faq relevan','data yang tersedia','saya cek data','saya cek faq','saya cek sheet','cek di sheet','cek di database'];
const keywordPattern = internalKeywords.join('|');
cleanOutput = cleanOutput.replace(new RegExp(`^\\s*([^.!?]*?(${keywordPattern})[^.!?]*[.!?]\\s*)`, 'i'), '');
cleanOutput = cleanOutput.replace(new RegExp(`^\\s*(${keywordPattern}).*?(\\n|\\.|$)`, 'i'), '');
cleanOutput = cleanOutput.replace(/^\s*(Berdasarkan|Menurut|Dari)\s+(data|faq|sheet|referensi)[^.!?]*[.!?]\s*/i, '');
if (!cleanOutput.trim() && preInternalStrip.trim()) cleanOutput = preInternalStrip;
cleanOutput = cleanOutput.trim();

// clean markdown (mask url dulu)
const urlRegex = /https?:\/\/[^\s)]+/g;
const maskedUrls = [];
cleanOutput = cleanOutput.replace(urlRegex, (m) => { maskedUrls.push(m); return `\x00URL${maskedUrls.length - 1}\x00`; });
cleanOutput = cleanOutput
  .replace(/\*\*([^*]+)\*\*/g, '$1').replace(/\*([^*]+)\*/g, '$1').replace(/_([^_]+)_/g, '$1')
  .replace(/~~([^~]+)~~/g, '$1').replace(/`([^`]+)`/g, '$1').replace(/[\*_~`]/g, '');
cleanOutput = cleanOutput
  .replace(/(\d)\s*[—–]\s*(\d)/g, '$1-$2').replace(/\s*[—–]\s*/g, ', ').replace(/\s*;\s*/g, ', ')
  .replace(/\s{2,}/g, ' ').replace(/\s+([,.])/g, '$1').replace(/,\s*,/g, ',').trim();
cleanOutput = cleanOutput.replace(/\x00URL(\d+)\x00/g, (_, idx) => maskedUrls[parseInt(idx)]);
cleanOutput = cleanOutput.replace(/(^|\n)([a-z])/g, (m, p1, p2) => p1 + p2.toUpperCase());

if (!cleanOutput || cleanOutput.trim() === '') {
  cleanOutput = isUnknown
    ? 'Maaf yaa, untuk yang ini saya belum ada infonya. Nanti saya cek dulu dan kabari lagi yaa.'
    : 'Maaf, ada kendala sebentar. Boleh diketik ulang yaa.';
}

// ── FAIL LOUD: tag survey ditolak -> JANGAN kirim konfirmasi palsu ──
// Setiap tag yang ditolak sistem harus MENGUBAH balasan, bukan cuma dibuang.
if (isSurveyIncomplete) {
  const tglOk = svTgl && !missingSlots.includes('tanggal');
  const jamOk = svJam && !missingSlots.includes('jam');
  if (missingSlots.includes('tanggal') && missingSlots.includes('jam')) {
    cleanOutput = `Boleh Kak, survey-nya enaknya kapan yaa? Misal ${contohTanggal} jam 10 pagi.`;
  } else if (missingSlots.includes('tanggal')) {
    cleanOutput = `Baik Kak, jam ${svJam} noted. Mau tanggal berapa yaa? Misal ${contohTanggal}.`;
  } else if (missingSlots.includes('jam')) {
    cleanOutput = `Baik Kak, untuk ${tglDisplay(svTgl)}. Jam berapa enaknya? Kami buka jam ${pad(openH)}.00 sampai ${pad(closeH)}.00 yaa.`;
  } else if (missingSlots.includes('unit')) {
    cleanOutput = `Baik Kak, untuk ${tglOk ? tglDisplay(svTgl) : 'jadwal itu'}${jamOk ? ' jam ' + svJam : ''}. Kira-kira mau lihat tipe unit yang mana yaa?`;
  } else if (/lewat|tahun/.test(surveyRejectReason)) {
    cleanOutput = `Boleh dikonfirmasi lagi tanggalnya Kak? Kalau ${contohTanggal} jam 10 pagi gimana?`;
  } else if (/tutup/.test(surveyRejectReason)) {
    cleanOutput = `Maaf Kak, di hari itu kami tutup. Boleh pilih hari lain? Misal ${contohTanggal} yaa.`;
  } else if (/jam operasional|jam tidak/.test(surveyRejectReason)) {
    cleanOutput = `Untuk jam segitu kami belum buka Kak. Survey bisa jam ${pad(openH)}.00 sampai ${pad(closeH)}.00 yaa, enaknya jam berapa?`;
  } else {
    cleanOutput = `Boleh dikonfirmasi lagi tanggal dan jamnya Kak? Misal ${contohTanggal} jam 10 pagi.`;
  }
  // survey belum jadi -> jangan biarkan aksi lain nyangkut di balasan yang sudah diganti
  isSendMedia = false;
  mediaKey = '';
}

// ── REQUEST_CALL: sisipkan admin_phone_display ──
if (isRequestCall) {
  const disp = (cfg.admin_phone_display) || '';
  if (disp && !cleanOutput.includes(disp)) cleanOutput = `${cleanOutput}\n\nBisa langsung telepon/WA ke ${disp} yaa.`;
}

// ── RESOLVE MEDIA URL + caption dari LINKS ──
// CHANGELOG 2026-07-18 (disambiguasi media, planning §Langkah 3):
//   Dulu: exact match -> substring .find() (ambil match PERTAMA) -> asal kirim baris teratas.
//   Sekarang: exact match tetap kirim; kalau exact gagal, kumpulkan SEMUA kandidat aktif
//   (substring Nama Link + kolom Keyword, lalu dipersempit kolom Tipe Unit bila key
//   mengandung pola tipe), dedup by URL, dan:
//     1 kandidat unik  -> kirim (seperti dulu)
//     >1 kandidat unik -> isMediaAmbiguous: override cleanOutput dengan pertanyaan pilihan
//                         (pola gate SURVEY — tag ditolak = balasan berubah), TIDAK kirim media,
//                         TIDAK notif tim (isSendMedia=false, isMediaManual=false)
//     0 kandidat       -> isMediaManual=true (jalur eskalasi existing, TIDAK berubah)
//   Field baru di return: isMediaAmbiguous, mediaCandidates. Field lama tidak diubah.
//   Konvensi: pakai $('Read LINKS Data').all() (Run Once for All Items), bukan .item.
// CHANGELOG 2026-07-22 (maps/website salah masuk jalur download+attach):
//   Row LINKS Tipe 'location'/'website' (mis. key "maps", "website") BUKAN file, cuma
//   URL. resolveRow() sekarang cek Tipe: kalau location/website -> JANGAN isi
//   mediaUrl/mediaCaption (supaya IF Send Media tidak trigger Download Media/Send Media
//   Kirimi), tempel URL-nya langsung sebagai teks ke cleanOutput, isSendMedia=false.
let mediaUrl = '', mediaCaption = '';
let isMediaManual = false, mediaRequestSummary = '';
let isMediaAmbiguous = false, mediaCandidates = [];
if (isSendMedia) {
  let linkRows = [];
  try { linkRows = $('Read LINKS Data').all().map(i => i.json); } catch (e) {}
  const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const digitsOf = s => String(s || '').replace(/\D/g, '');
  const active = linkRows.filter(r => /^\s*(aktif|active|on|ya)\s*$/i.test(String(r['Status'] || '')));

  const resolveRow = (row) => {
    const tipeRow = norm(row['Tipe']);
    if (tipeRow === 'location' || tipeRow === 'website') {
      // Bukan file media, cuma URL -> jangan lewat Download Media/Send Media Kirimi.
      // Tempel sebagai teks biasa ke balasan yang sudah ada.
      isSendMedia = false;
      const url = String(row['URL'] || '').trim();
      const label = String(row['Caption'] || row['Deskripsi'] || '').trim();
      if (url) {
        const line = label ? `${label} ${url}` : url;
        cleanOutput = cleanOutput.trim() ? `${cleanOutput}\n\n${line}` : line;
      }
      return;
    }
    mediaUrl = String(row['URL'] || '').trim();
    mediaCaption = String(row['Caption'] || row['Deskripsi'] || '').trim() || 'Ini file yang diminta yaa.';
  };

  // 1) EXACT match Nama Link == key -> kirim (perilaku existing dipertahankan)
  const exactRow = active.find(r => norm(r['Nama Link']) === mediaKey);
  if (exactRow && String(exactRow['URL'] || '').trim()) {
    resolveRow(exactRow);
  } else {
    // 2) FALLBACK: kumpulkan SEMUA kandidat aktif (Array.filter, bukan .find).
    //   (0) saring pool per jenis media (foto->image / video->video),
    //   (a) substring Nama Link + (b) Keyword (cocok PER-TOKEN),
    //   (c) persempit kolom Tipe Unit bila key mengandung pola tipe (3672/3681/3060).
    //   QUALIFIER GATE: kalau key punya kata pembeda yang TIDAK ada di kandidat mana pun
    //   (mis. "foto-interior" -> "interior" tak ada di katalog) -> kandidat dikosongkan
    //   supaya jatuh ke eskalasi manual, bukan salah tanya tipe.
    const tokensOf = s => norm(s).split(/[^a-z0-9]+/i).filter(Boolean);
    const GENERIC = new Set(['foto','gambar','photo','potret','video','klip','movie','denah','siteplan','brosur','katalog','price','pricelist','list','unit','rumah','tipe','type','file','media','minta','contoh']);
    const keyTokens = tokensOf(mediaKey);
    const keyDigits = digitsOf(mediaKey);            // "foto-36-72" -> "3672", "foto" -> ""
    const hasTypePattern = keyDigits.length >= 4;    // tipe PCR = 4 digit
    const qualifiers = keyTokens.filter(t => !GENERIC.has(t) && !/^\d+$/.test(t) && t.length >= 3);

    // jenis media yang diminta -> saring pool lewat kolom Tipe (image/video/document)
    let wantTipe = null;
    if (/\bvideo\b|klip|movie/.test(mediaKey)) wantTipe = 'video';
    else if (/foto|gambar|photo|potret|denah|siteplan|brosur|katalog|price/.test(mediaKey)) wantTipe = 'image';
    let pool = active;
    if (wantTipe) { const p = active.filter(r => norm(r['Tipe']) === wantTipe); if (p.length) pool = p; }

    const rowBag = (r) => [...tokensOf(r['Keyword']), ...tokensOf(r['Nama Link'])];
    const nameMatch = (r) => { const nl = norm(r['Nama Link']); return !!nl && (nl.includes(mediaKey) || mediaKey.includes(nl)); };
    const keywordMatch = (r) => tokensOf(r['Keyword']).some(kw => keyTokens.includes(kw));
    const typeUnitMatch = (r) => { const tuD = digitsOf(r['Tipe Unit']); return tuD.length >= 4 && (keyDigits === tuD || keyDigits.includes(tuD)); };

    // (a) substring Nama Link + (b) Keyword per-token + (c) Tipe Unit
    let candidates = pool.filter(r => nameMatch(r) || keywordMatch(r) || typeUnitMatch(r));
    // QUALIFIER GATE: kandidat wajib memenuhi minimal satu kata pembeda yang diminta
    if (qualifiers.length) {
      candidates = candidates.filter(r => { const bag = rowBag(r); return qualifiers.some(q => bag.includes(q)); });
    }
    // (c) Tipe Unit: bila key mengandung pola tipe, PERSEMPIT ke tipe itu
    if (hasTypePattern) {
      const typedIn = candidates.filter(typeUnitMatch);
      if (typedIn.length) candidates = typedIn;
    }

    // dedup by URL — baris beda tipe tapi URL sama (video 36/72 & 36/81) = 1 kandidat.
    // Simpan tipe unit yang ter-group per URL untuk menyusun pertanyaan pilihan.
    const byUrl = new Map();
    for (const r of candidates) {
      const u = String(r['URL'] || '').trim();
      if (!u) continue;
      if (!byUrl.has(u)) byUrl.set(u, { row: r, tipes: [] });
      const g = byUrl.get(u);
      const tu = String(r['Tipe Unit'] || '').trim();
      if (tu && !g.tipes.includes(tu)) g.tipes.push(tu);
    }
    const unique = [...byUrl.values()];

    if (unique.length === 1) {
      // 1 kandidat unik (termasuk kasus "semua kandidat share 1 URL") -> kirim
      resolveRow(unique[0].row);
    } else if (unique.length > 1) {
      // >1 kandidat unik -> AMBIGU: sistem yang bertanya, media TIDAK dikirim, tim TIDAK dinotif
      isMediaAmbiguous = true;
      isSendMedia = false;
      isMediaManual = false;
      mediaUrl = '';
      mediaCaption = '';

      mediaCandidates = unique.map(g => ({
        key: String(g.row['Nama Link'] || '').trim(),
        tipeUnit: g.tipes.join(' / ')
      }));

      // label human-readable per kandidat, mis. "tipe 36/72", "tipe 30/60 subsidi"
      const labelFor = (g) => {
        const nl = norm(g.row['Nama Link']);
        const kw = norm(g.row['Keyword']);
        const isSub = /subsidi/.test(nl) || /subsidi/.test(kw) || g.tipes.includes('30/60');
        const tp = g.tipes.length ? g.tipes.join(', ') : String(g.row['Tipe Unit'] || '').trim();
        if (!tp) return nl;
        return 'tipe ' + tp + (isSub ? ' subsidi' : '');
      };
      // kata benda media (foto/video) — dari Tipe kandidat atau dari key
      const isVideo = /video/.test(mediaKey) || unique.every(g => /video/i.test(String(g.row['Tipe'] || '')));
      const noun = isVideo ? 'video' : 'foto';

      const opts = unique.map(labelFor);
      let optText;
      if (opts.length <= 1) optText = opts.join('');
      else if (opts.length === 2) optText = `${opts[0]} atau ${opts[1]}`;
      else optText = `${opts.slice(0, -1).join(', ')}, atau ${opts[opts.length - 1]}`;

      // OVERRIDE balasan (pola gate SURVEY). Satu pertanyaan saja, gaya konsisten bot.
      cleanOutput = `Boleh Kak 😊 Mau ${noun} unit tipe yang mana yaa, ${optText}?`;
      console.log('SEND_MEDIA ambigu, tanya balik:', JSON.stringify(mediaCandidates));
    } else {
      // 0 kandidat -> fallback NOTIFIKASI MANUAL ke tim telemarketer (jalur existing)
      console.warn('SEND_MEDIA key tidak ada di LINKS, fallback manual:', mediaKey);
      isSendMedia = false;
      isMediaManual = true;
      const userMsg = (preprocess && preprocess.actualUserMessage) || originalMessage || '';
      mediaRequestSummary = (mediaKey ? ('key="' + mediaKey + '" ') : '') + (userMsg ? ('| pesan user: ' + String(userMsg).slice(0, 300)) : '');
    }
  }
}
// ── #3: MEDIA KE-2 (foto + video dalam satu balasan) ──
// Kirim media kedua HANYA jika media-1 sukses (bukan ambigu/manual/location) DAN ada tag
// kedua dengan KEY KANONIK yang exact-match di LINKS. Kalau tidak memenuhi -> dilewati
// diam-diam (tidak tanya balik, tidak notif). Jalur media-1 di atas tidak diubah.
let isSendMedia2 = false, mediaUrl2 = '', mediaCaption2 = '';
if (isSendMedia && mediaUrl && !isMediaAmbiguous && mediaKeysAll.length >= 2) {
  let linkRows2 = [];
  try { linkRows2 = $('Read LINKS Data').all().map(i => i.json); } catch (e) {}
  const norm2 = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const active2 = linkRows2.filter(r => /^\s*(aktif|active|on|ya)\s*$/i.test(String(r['Status'] || '')));
  const key2 = mediaKeysAll.find(k => k && k !== mediaKey) || '';
  const row2 = key2 ? active2.find(r => norm2(r['Nama Link']) === key2) : null;
  if (row2) {
    const tipe2 = norm2(row2['Tipe']);
    const url2 = String(row2['URL'] || '').trim();
    if (url2 && url2 !== mediaUrl && tipe2 !== 'location' && tipe2 !== 'website') {
      isSendMedia2 = true;
      mediaUrl2 = url2;
      mediaCaption2 = String(row2['Caption'] || row2['Deskripsi'] || '').trim() || 'Ini file berikutnya yaa.';
      // urutan foto -> video: kalau media-1 video & media-2 image, tukar posisi.
      const row1 = active2.find(r => norm2(r['Nama Link']) === mediaKey);
      const tipe1 = row1 ? norm2(row1['Tipe']) : '';
      if (tipe1 === 'video' && tipe2 === 'image') {
        const tU = mediaUrl, tC = mediaCaption;
        mediaUrl = mediaUrl2; mediaCaption = mediaCaption2;
        mediaUrl2 = tU; mediaCaption2 = tC;
      }
    }
  }
}

// ── GUARD: NOMINAL RUPIAH HALUSINASI (2026-08-21) ──
// Insiden 6281291218300: VIRA menyebut "Rp 1.150.000.000" untuk Tipe 36/81 (asli Rp 409.294.258)
// dan "Rp 420.000.000" untuk subsidi (asli Rp 185.000.000). Instruksi anti-halusinasi di system
// prompt sudah ada tapi tidak ditaati. Guard ini deterministik: nominal apa pun di balasan yang
// tidak bersumber dari PRODUK/FAQ/pesan user ditahan, tidak peduli model apa yang dipakai.
// AUDIT-FIX #3: blok ini SENGAJA diletakkan SEBELUM register survey (surveyPendingWrite) supaya
// pembatalan isScheduleSurvey ikut terhitung. Di posisi lama (sesudahnya) balasan user diganti
// tapi survey tetap tertulis ke sheet dan tim lapangan tetap dinotif jadwal yang tak pernah
// dikonfirmasi ke user.
const retr = (() => { for (const nm of ['FAQ Retrieve', 'FAQ Retrieve1']) { try { return $(nm).first().json; } catch (e) {} } return {}; })();
const _amt = (text) => {
  const out = []; const s = String(text || ''); let m;
  const reRp = /rp\s*([\d][\d.,]*)/gi;
  while ((m = reRp.exec(s)) !== null) { const n = parseInt(m[1].replace(/[^\d]/g, ''), 10); if (n > 0) out.push(n); }
  // AUDIT-FIX #4: pola angka berpemisah TANPA kata "Rp". Sebelumnya hanya ada di pembangun
  // whitelist (FAQ Retrieve) tapi tidak di pemeriksa ini -> "harganya 1.150.000.000 Kak" lolos.
  const reSep = /\b(\d{1,3}(?:[.,]\d{3}){2,})\b/g;
  while ((m = reSep.exec(s)) !== null) { const n = parseInt(m[1].replace(/[^\d]/g, ''), 10); if (n > 0) out.push(n); }
  const reUnit = /(\d+(?:[.,]\d+)?)\s*(juta|jt|miliar|milyar)\b/gi;
  while ((m = reUnit.exec(s)) !== null) {
    const base = parseFloat(m[1].replace(',', '.'));
    const n = Math.round(base * (/^(juta|jt)$/i.test(m[2]) ? 1e6 : 1e9)); if (n > 0) out.push(n);
  }
  return out;
};
// AUDIT-FIX #5: whitelist ikut memuat SELURUH teks user giliran ini (buffer debounce bisa berisi
// beberapa pesan beruntun), bukan cuma original_message. Mengurangi false positive saat user
// menyebut budget lalu AI mengutipnya balik. Kasus lintas-giliran penuh belum tertutup - histori
// itu hanya ada di memory AI Agent, tidak tersedia di node ini. Sisa risikonya TERLIHAT, bukan
// senyap: guard mengeskalasi ke admin lewat needs_unknown.
const userTexts = [originalMessage];
try { const cu = $('Cek_user_status').first().json; if (cu && cu.user_message_final) userTexts.push(cu.user_message_final); } catch (e) {}
if (preprocess && preprocess.actualUserMessage) userTexts.push(preprocess.actualUserMessage);
const allowed = [...(Array.isArray(retr.allowedAmounts) ? retr.allowedAmounts : []),
                 ...userTexts.flatMap(t => _amt(t))];
// Toleransi 1%: "Rp 383 juta" sah terhadap data 383.004.784, tapi 420 juta vs 409 juta tetap ditolak.
const isGrounded = (x) => allowed.some(a => Math.abs(a - x) <= Math.max(1, a * 0.01));
const MIN_CEK = 1000000; // di bawah 1 juta (luas, tenor, tahun, jumlah kamar) tidak relevan
const badAmounts = [...new Set(_amt(cleanOutput).filter(x => x >= MIN_CEK && !isGrounded(x)))];

// ── CANARY: SUMBER DATA TIDAK TERBACA (2026-08-21) ──
// AUDIT-FIX #1: syaratnya kini mencakup _diag yang HILANG dan faq_error, bukan cuma hitungan 0.
// '_diag tidak ada' berarti FAQ Retrieve gagal total ATAU node-nya sendiri tak terbaca - dua
// keadaan yang dulu lolos diam-diam karena `undefined === 0` bernilai false.
const _d = retr._diag || {};
const dataOutage = !retr._diag || !!retr.faq_error || !!_d.error || _d.prod === 0 || _d.faq === 0;
const factualTurn = !!(preprocess && (preprocess.askingPrice || preprocess.askingKPR || preprocess.askingLokasi
  || preprocess.askingLegalitas || preprocess.askingFasilitas || preprocess.discussingUnit));

// Pembatalan aksi backend dipakai bersama oleh price guard dan canary: kalau balasan yang dilihat
// user diganti, TIDAK BOLEH ada state yang tetap berubah diam-diam di belakangnya.
const batalkanAksi = () => {
  isUnknown = true;
  isSendMedia = false; isSendMedia2 = false; mediaKey = '';
  // isScheduleSurvey dimatikan SEBELUM surveyPendingWrite dihitung -> slot pending justru
  // DIPERTAHANKAN (bukan dikosongkan), sehingga giliran berikutnya bisa konfirmasi ulang.
  isScheduleSurvey = false; surveyData = {};
  // isRequestCall / isTalkToAdmin sengaja TIDAK dimatikan: keduanya jalur eskalasi ke manusia
  // dan memakai pesan user mentah, bukan cleanOutput - justru harus tetap jalan.
};

let priceGuardTripped = false;
if (badAmounts.length) {
  priceGuardTripped = true;
  console.error('PRICE GUARD: nominal tak bersumber -> ' + badAmounts.join(', ') + ' | balasan ditahan: ' + cleanOutput.substring(0, 200));
  cleanOutput = 'Sebentar yaa Kak, untuk angka pastinya saya konfirmasi dulu ke tim biar tidak salah info. Nanti saya kabari lagi 🙏';
  batalkanAksi();
}
if (dataOutage) {
  console.error('DATA OUTAGE: prod=' + _d.prod + ' faq=' + _d.faq + ' links=' + _d.links
    + ' missing=' + JSON.stringify(_d.missing || []) + ' error=' + (retr.faq_error || _d.error || '-'));
  if (factualTurn && !priceGuardTripped) {
    cleanOutput = 'Sebentar yaa Kak, datanya lagi saya cek dulu. Nanti saya kabari lagi 🙏';
    batalkanAksi();
  }
}

// ── NOTIF ADMIN: hanya untuk survey reject kategori AI-FAULT ──
// Kasus normal (slot belum lengkap / di luar jam operasional / hari tutup) TIDAK dinotif,
// supaya admin tidak banjir alarm dari perilaku yang memang benar. Hanya kegagalan
// prompt (halusinasi tanggal/jam/tahun, format tag salah) yang di-flag.
const AI_FAULT_REASONS = ['tanggal tidak terbaca', 'jam tidak terbaca', 'jam tidak valid', 'tahun tidak valid', 'tanggal/jam sudah lewat'];
const surveyNeedsAdminAlert = isSurveyIncomplete && AI_FAULT_REASONS.some(r => surveyRejectReason.includes(r));

// register #1: slot yang dipersist ke STATS.
// Survey sukses tercatat -> kosongkan. Selain itu bawa maju slot terbaru (tag menang, pending cadangan).
const pendTglOut = svTgl || pendingSv.tanggal || '';
const pendJamOut = svJam || pendingSv.jam || '';
const pendUnitOut = svUnit || pendingSv.unit || '';
const surveyPendingWrite = (isScheduleSurvey || svHallucinated || !(pendTglOut || pendJamOut || pendUnitOut))
  ? { tanggal: '', jam: '', unit: '', ts: '' }
  : { tanggal: pendTglOut, jam: pendJamOut, unit: pendUnitOut, ts: Math.floor(Date.now() / 1000) };

return [{
  json: {
    ...chatCounter, ...preprocess, ...item.json,
    cleanOutput,
    isScheduleSurvey, surveyData,
    isSurveyIncomplete, missingSlots, surveyRejectReason,
    surveyNeedsAdminAlert,
    surveyPendingWrite,
    aiOutputRaw: aiOutput,
    isRequestCall,
    isTalkToAdmin,
    isSendMedia, mediaUrl, mediaCaption, mediaKey,
    isSendMedia2, mediaUrl2, mediaCaption2,
    isMediaManual, mediaRequestSummary,
    isMediaAmbiguous, mediaCandidates,
    isUnknown,
    needs_unknown: isUnknown ? 'true' : 'false',
    priceGuardTripped, badAmounts, dataOutage, retrieveDiag: _d,
    original_message: originalMessage,
    is_new_user: isNewUser,
    unit_interest_merged: unitMerged,
    budget_range_merged: budgetMerged,
    unit_changed: unitChanged,
    budget_changed: budgetChanged,
    nama_lengkap_merged: namaMerged,
    lokasi_kerja_merged: lokasiKerjaMerged,
    nama_changed: namaChanged,
    lokasi_kerja_changed: lokasiKerjaChanged
  }
}];

// FORMAT MEDIA NOTIF — notifikasi manual ke tim telemarketer (Aar & Aqsa).
// Dipakai saat user minta gambar/video/brosur TAPI file belum ada di katalog
// LINKS (native send tak bisa). Tim kirim file-nya manual ke user.
// Mengembalikan 1 item per nomor tim (loop kirim di Notify Media Team).
const pa = $('Process All').first().json;
const cc = $('Chat Counter').first().json;
const key = $('Resolve User Row').first().json.resolved_key || cc.user_wa || '';
const nama = cc.user_name || '';
const mediaKey = pa.mediaKey || '';
const summary = pa.mediaRequestSummary || '';

const message = `📸 [PCR] PERMINTAAN MEDIA - KIRIM MANUAL
User: ${key}
Nama: ${nama || '(belum ada nama)'}
Diminta: ${mediaKey || 'foto/video'}
Detail: ${summary || '(tidak ada detail)'}

User menunggu file dikirim. Balas langsung ke user yaa.
Chat: wa.me/${String(key).replace(/\D/g, '')}`;

const cfg = $('Parse Config').first().json.config;
let tujuan = Array.isArray(cfg.media_team_phone) ? cfg.media_team_phone : [cfg.media_team_phone];
tujuan = (tujuan || []).filter(Boolean);
if (!tujuan.length) { console.warn('media_team_phone kosong — tidak ada tujuan notif media manual.'); return []; }

return tujuan.map(no => ({ json: { phone: String(no), message } }));

// COLLECT HANDOVER CONTEXT — STATS (fakta persisten) + MSG_BUFFER (transkrip sesi).
const digits = v => String(v ?? '').replace(/\D/g, '');
const key = $('Resolve User Row').first().json.resolved_key;

let statsRow = {};
try { statsRow = $('Read User STATS').all().map(i => i.json).find(r => digits(r['No WA']) === digits(key)) || {}; } catch (e) {}

let transcript = '';
try {
  const buf = $('Read MSG_BUFFER').all().map(i => i.json)
    .filter(r => digits(r['no_wa']) === digits(key))
    .sort((a, b) => Number(a.ts) - Number(b.ts));
  transcript = buf.map(r => `User: ${r.message}`).join('\n');
} catch (e) {}

const pa = $('Process All').first().json;
const sd = pa.surveyData || {};
const profil = {
  // PRIORITAS: [FACTS] turn ini > nama_lengkap tersimpan > push name WA.
  // JANGAN pakai statsRow['Nama'] duluan — itu nama akun WhatsApp, bukan nama
  // yang user sebutkan. (Bug 2026-07-20: user bilang "Hera", handover kirim
  // "Steven Leroy" karena kolom 'Nama' selalu terisi push name.)
  nama: pa.nama_lengkap_merged || statsRow['nama_lengkap'] || statsRow['Nama'] || $('Chat Counter').first().json.user_name || '',
  // Simpan push name terpisah: kalau beda dengan nama asli, itu info berguna
  // untuk tim lapangan (mis. yang chat istri, akun WA atas nama suami).
  nama_akun_wa: statsRow['Nama'] || $('Chat Counter').first().json.user_name || '',
  lokasi_kerja: pa.lokasi_kerja_merged || statsRow['lokasi_kerja'] || '',
  no_wa: key,
  pesan_pertama: statsRow['Pesan Pertama'] || '',
  unit_interest: pa.unit_interest_merged || statsRow['unit_interest'] || '',
  budget_range: pa.budget_range_merged || statsRow['budget_range'] || '',
  survey: [sd.tanggal, sd.jam, 'SCHEDULED'].filter(Boolean).join(' '),
  lead_source: $('Detect Lead Source').first().json.lead_source_final || statsRow['lead_source'] || '',
  jumlah_chat: statsRow['Counter'] || '',
};

return [{ json: {
  handover_profil: profil,
  handover_transcript: transcript || '(transkrip sesi tidak tersedia)',
  handover_trigger: 'DELEGATION'
}}];

parameters.text:
=Kamu asisten internal yang merangkum percakapan calon pembeli properti untuk tim telemarketer/admin Persada Cisoka Residence. Buat ringkasan SINGKAT, PADAT, FAKTUAL dalam Bahasa Indonesia. Hanya gunakan DATA PROFIL dan TRANSKRIP di bawah. JANGAN mengarang, tulis "belum diketahui" bila kosong. Tanpa basa-basi. Kalau "Nama akun WA" berbeda dari "Nama", pakai "Nama" dan sebutkan akun WA-nya dalam kurung. Kalau sama, sebut sekali saja.

ATURAN FORMAT (WAJIB): keluarkan PLAIN TEXT murni. DILARANG memakai markdown — tanpa tanda bintang (* atau **), tanpa underscore, tanpa backtick, tanpa heading (#), tanpa bullet simbol. Tulis label apa adanya, contoh: Profil Klien: ...

Keluarkan PERSIS format berikut:
Profil Klien: <nama, domisili, no WA, sumber>
Kebutuhan: <apa yang dicari, 1-2 kalimat>
Tipe Unit Diminati: <tipe, atau belum diketahui>
BUDGET/KPR: <kisaran/skema, atau belum dibahas>
Status Survey: <SCHEDULED tgl jam / belum dijadwalkan>
Poin Penting: <objections/kendala/urgensi, maks 3 poin>
Ringkasan: <1 kalimat konkret>

DATA PROFIL:
Nama: {{ $json.handover_profil.nama }}
Nama akun WA: {{ $json.handover_profil.nama_akun_wa }}
Lokasi Kerja: {{ $json.handover_profil.lokasi_kerja }}
No WA: {{ $json.handover_profil.no_wa }}
Sumber: {{ $json.handover_profil.lead_source }}
Unit diminati (sistem): {{ $json.handover_profil.unit_interest }}
Budget (sistem): {{ $json.handover_profil.budget_range }}
Status survey (sistem): {{ $json.handover_profil.survey }}
Jumlah chat: {{ $json.handover_profil.jumlah_chat }}

TRANSKRIP SESI:
{{ $json.handover_transcript }}

parameters.jsCode:
// FORMAT HANDOVER MESSAGE — bungkus ringkasan LLM (atau fallback deterministik).

// Sanitizer: buang sisa markdown dari output LLM. Prompt sudah minta plain text,
// tapi LLM masih sering bocor bold (**...** / *...*) — WA tidak butuh formatting,
// dan bintang yang tertinggal bikin pesan tim lapangan terlihat kotor.
// Underscore sengaja TIDAK dihapus: berisiko kena nama kolom (unit_interest, dll).
const stripMd = s => String(s || '')
  .replace(/\*/g, '')             // ** dan *
  .replace(/`/g, '')              // backtick
  .replace(/^#{1,6}\s*/gm, '')    // heading markdown
  .replace(/[ \t]+$/gm, '')       // trailing space
  .replace(/\n{3,}/g, '\n\n')     // rapikan blank line beruntun
  .trim();

let summary = '';
try { const s = $('Summarize Handover').first().json; summary = (s.content && s.content[0] && s.content[0].text) || s.text || ''; } catch (e) {}
summary = stripMd(summary);

const ctx = $('Collect Handover Context').first().json;
const p = ctx.handover_profil || {};
const trigger = ctx.handover_trigger || 'DELEGATION';

if (!summary || !summary.trim()) {
  summary = `PROFIL KLIEN: ${p.nama || '-'}${p.lokasi_kerja ? ', ' + p.lokasi_kerja : ''}, ${p.no_wa || '-'}, sumber ${p.lead_source || 'belum diketahui'}
TIPE UNIT DIMINATI: ${p.unit_interest || 'belum diketahui'}
BUDGET/KPR: ${p.budget_range || 'belum dibahas'}
STATUS SURVEY: ${p.survey || 'belum dijadwalkan'}`;
}

const header = {
  DELEGATION: '🏠 [PCR] SURVEY BARU — HANDOVER KE TIM LAPANGAN',
  HITL: '🙋 [PCR] AMBIL ALIH CHAT',
  CALL: '📞 [PCR] MINTA DITELEPON',
}[trigger] || '📋 [PCR] HANDOVER';

const message = `${header}

${summary}

— Chat: wa.me/${p.no_wa}`;

const cfg = $('Parse Config').first().json.config;
let tujuan = (trigger === 'DELEGATION')
  ? (Array.isArray(cfg.field_team_phone) ? cfg.field_team_phone : [cfg.field_team_phone])
  : [cfg.admin_phone];
tujuan = (tujuan || []).filter(Boolean);
if (!tujuan.length) { console.warn('Tidak ada nomor tujuan handover (field_team_phone kosong).'); return []; }

return tujuan.map(no => ({ json: { phone: String(no), message } }));

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.original_message;   // ← perbaikan utama

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// ====================================================================
// PROCESS COUNTER & MERGE DATA (V4)
// Fix: (1) matching row No WA primer / lid backup (bukan lid-only),
//      (2) "Tanggal Chat Pertama" dibaca dari kolom yang benar
//          (dulu baca existingRow.Tanggal yang tidak ada -> tanggal
//          pertama ter-reset jadi hari ini setiap pesan),
//      (3) error -> stop (return []) alih-alih menulis row "ERROR".
// ====================================================================
const debugLog = [];

try {
    const allItems = $input.all();
    debugLog.push("Step 1: Received " + allItems.length + " items from Read STATS");

    const chatCounter = $('Chat Counter').first().json;
    const resolve = $('Resolve User Row').first().json;
    const resolvedKey = resolve.resolved_key;

    const userName = chatCounter.user_name || "User";
    const userMessage = chatCounter.original_message || "";
    const digits = v => String(v ?? '').replace(/\D/g, '');
    const phone = digits(chatCounter.user_phone);
    const lid = digits(chatCounter.user_lid);

    if (!resolvedKey) {
        console.warn("resolved_key kosong - skip update STATS");
        return [];
    }

    // Process sheet rows
    const sheetRows = allItems
        .filter(item => {
            const data = item?.json || item;
            if (!data || Object.keys(data).length === 0) return false;
            return !!(data['lid'] || data['No WA'] || data.no_wa || data.NoWA);
        })
        .map(item => item?.json || item);

    debugLog.push("Step 2: Sheet rows found: " + sheetRows.length);

    // Find existing row: No WA primer, lid backup (konsisten dgn Resolve User Row)
    let existingRow = null;
    if (phone) existingRow = sheetRows.find(r => digits(r['No WA']) === phone) || null;
    if (!existingRow && lid) {
        existingRow = sheetRows.find(r => digits(r['lid']) === lid)
                   || sheetRows.find(r => digits(r['No WA']) === lid)
                   || null;
    }

    const isNewUser = !existingRow;
    debugLog.push("Step 3: " + (isNewUser ? "NEW USER" : "EXISTING USER"));

    let counter, pesanPertama, tanggalPertama, intensitasChat;

    if (existingRow) {
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;

        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && String(pesanLama).trim() !== '') ? pesanLama : userMessage;

        // V4 FIX: baca kolom yang benar
        const tglLama = existingRow['Tanggal Chat Pertama'];
        tanggalPertama = (tglLama && String(tglLama).trim() !== '') ? tglLama : null;
    } else {
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;
    }

    if (!tanggalPertama) {
        tanggalPertama = new Date().toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
        });
    }

    // -- KONTEKS (2026-08-27): jangkar mentah + ringkasan lama --------------
    // last_msgs = 3 pesan user terakhir APA ADANYA. Ditulis kode, bukan AI.
    // Ini yang dipakai "Update Konteks" untuk mengoreksi ringkasan yang mulai
    // melenceng (ringkasan-dari-ringkasan gampang hanyut), dan yang dibaca
    // workflow Follow-up kalau ringkasannya kosong.
    const K_SEP = ' || ';
    // Cap sengaja ketat: STATS dibaca SELURUH TAB 3x per pesan masuk
    // (Read User STATS, Read STATS for HITL, Read STATS). Tiap karakter di
    // sini dikali 3 x jumlah lead, tiap pesan. Pesan WA di sini rata-rata
    // 10-80 char, jadi 150 sudah menampung mayoritas utuh.
    const K_MAX_ONE = 150;   // batas per pesan
    const K_MAX_ALL = 450;   // batas isi sel

    let pesanTerakhir = '';
    try { pesanTerakhir = String($('Cek_user_status').first().json.user_message_final || ''); } catch (e) {}
    if (!pesanTerakhir.trim()) pesanTerakhir = userMessage;

    const msgsLama = String((existingRow && existingRow['last_msgs']) || '')
        .split(K_SEP).map(s => s.trim()).filter(Boolean);
    if (pesanTerakhir.trim()) msgsLama.push(pesanTerakhir.trim().slice(0, K_MAX_ONE));
    const lastMsgs = msgsLama.slice(-3).join(K_SEP).slice(0, K_MAX_ALL);

    const konteksLama = String((existingRow && existingRow['konteks']) || '');
    const konteksTsLama = (existingRow && existingRow['konteks_ts']) || '';

    const outputData = {
        "No WA": resolvedKey,
        "lid": lid,
        "Tanggal": tanggalPertama,
        "TanggalSekarang": new Date().toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta', day: '2-digit', month: '2-digit', year: 'numeric'
        }),
        "Nama": userName,
        "Pesan Pertama": pesanPertama,
        "Counter": counter,
        "Intensitas Chat": intensitasChat,
        "last_msgs": lastMsgs,
        "konteks_lama": konteksLama,
        "konteks_ts_lama": konteksTsLama
    };

    return [{ json: outputData }];

} catch (error) {
    // V4 FIX: jangan menulis row "ERROR" ke sheet - cukup log & stop.
    console.error("Process Counter ERROR: " + error.message, debugLog);
    return [];
}

// ====================================================================
// BUILD KONTEKS INPUT (2026-08-27)
// Rakit bahan untuk node "Update Konteks".
// Jalur ini ada SESUDAH balasan terkirim ke user, tapi satu rangkaian dengan
// "Update to STATS" - jadi satu field yang gagal dibaca TIDAK boleh
// menggagalkan penulisan state user. Semua akses lintas-node dibungkus.
// ====================================================================
const base = $input.first().json;

const g = (fn, dflt) => {
  try { const v = fn(); return (v === undefined || v === null || v === '') ? dflt : v; }
  catch (e) { return dflt; }
};

const pa = g(() => $('Process All').first().json, {});

return [{ json: {
  ...base,
  k_konteks_lama: String(base.konteks_lama || ''),
  k_last_msgs:    String(base.last_msgs || ''),
  k_balasan_vira: String(g(() => pa.cleanOutput, '')).slice(0, 600),
  k_unit:         String(g(() => pa.unit_interest_merged, '')),
  k_budget:       String(g(() => pa.budget_range_merged, '')),
  k_lokasi:       String(g(() => pa.lokasi_kerja_merged, '')),
  k_nama:         String(g(() => pa.nama_lengkap_merged, base.Nama || '')),
  k_sumber:       String(g(() => $('Detect Lead Source').first().json.lead_source_final, '')),
  k_jumlah_chat:  String(base.Counter || '')
}}];

parameters.text:
=Kamu memperbarui CATATAN KONTEKS internal tentang satu calon pembeli properti Persada Cisoka Residence. Catatan ini dipakai tim dan workflow follow-up. User TIDAK pernah membacanya.

Sumber yang boleh dipakai HANYA empat blok di bawah. DILARANG menambah fakta, angka, tanggal, promo, atau janji yang tidak ada di sana. Kalau giliran ini tidak menambah informasi baru, keluarkan KONTEKS SEBELUMNYA apa adanya. Kalau ada informasi yang bertentangan, yang lebih baru menang.

ATURAN FORMAT (WAJIB):
- PLAIN TEXT murni. Tanpa markdown, tanpa bintang, tanpa backtick, tanpa heading.
- Bahasa Indonesia, padat, tanpa basa-basi.
- Maksimal 500 karakter total.
- Keluarkan PERSIS 5 baris berikut, tanpa baris lain sebelum atau sesudahnya:

TOPIK: <yang sedang dibahas user, 1 kalimat>
KEBUTUHAN: <yang dia cari atau butuhkan>
KEBERATAN: <hambatan atau keraguan yang dia sebut sendiri, atau tanda minus kalau belum ada>
LANGKAH BERIKUT: <hal paling masuk akal untuk ditawarkan berikutnya>
CATATAN: <maks 1 kalimat penting lain, atau tanda minus>

KONTEKS SEBELUMNYA:
{{ $json.k_konteks_lama || '(belum ada)' }}

PESAN TERAKHIR USER (urut lama ke baru):
{{ $json.k_last_msgs || '(tidak ada)' }}

BALASAN VIRA BARUSAN:
{{ $json.k_balasan_vira || '(tidak ada)' }}

FAKTA TERCATAT SISTEM:
Nama: {{ $json.k_nama || '-' }}
Unit diminati: {{ $json.k_unit || '-' }}
Budget: {{ $json.k_budget || '-' }}
Lokasi kerja: {{ $json.k_lokasi || '-' }}
Sumber: {{ $json.k_sumber || '-' }}
Jumlah chat: {{ $json.k_jumlah_chat || '-' }}

parameters.jsCode:
// ====================================================================
// MERGE KONTEKS (2026-08-27)
// WAJIB ada, bukan hiasan. "Update to STATS" membaca $json.lid dari item yang
// masuk; output chainLlm bentuknya {text: ...}, jadi kalau disambung langsung
// kolom lid di sheet bisa tertimpa kosong. Sekalian validasi + fallback.
// ====================================================================
const stripMd = s => String(s || '')
  .replace(/\*/g, '')
  .replace(/`/g, '')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/[ \t]+$/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const base = $('Build Konteks Input').first().json;
const konteksLama = String(base.k_konteks_lama || '');

let hasil = '';
try {
  const s = $input.first().json;
  hasil = (s.content && s.content[0] && s.content[0].text) || s.text || '';
} catch (e) {}
hasil = stripMd(hasil);

// Gagal / kosong / tidak berformat -> PERTAHANKAN yang lama.
// Jangan pernah menimpa catatan yang sudah benar dengan hasil panggilan gagal.
const valid = hasil.length > 20 && /(^|\n)\s*TOPIK\s*:/i.test(hasil);
if (!valid) console.warn('Update Konteks tidak valid/kosong - konteks lama dipertahankan');

const konteksFinal = valid ? hasil.slice(0, 500) : konteksLama;
const berubah = konteksFinal !== konteksLama;

return [{ json: {
  ...base,
  konteks_final: konteksFinal,
  konteks_ts: berubah ? Math.floor(Date.now() / 1000) : (base.konteks_ts_lama || '')
}}];

// ====================================================================
// UPDATE GREETING FLAG (V4 - disederhanakan)
// Dulu: pattern-matching teks balasan (rapuh, tergantung susunan
// kalimat). Sekarang: cukup dari flag is_new_user — kalau eksekusi
// ini mengirim intro ke user baru (reply sudah SUKSES terkirim
// karena node ini jalan setelah Reply Chat Kirimi), tandai Y.
// ====================================================================
const isNewUser = $('Cek_user_status').first().json.is_new_user === true;

if (isNewUser) {
  console.log('📝 [GREETING] intro terkirim ke user baru -> greeting_sent = Y');
}

return [{
  json: {
    update_needed: isNewUser ? 'true' : 'false',
    greeting_sent: 'Y'
  }
}];
